 "content": "def transform(grid):
    """Move the patterned object next to the full 2-colored guide, and mark its far edge."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    guide_rows = [r for r in range(h) if all(v == 2 for v in g[r])]
    guide_cols = [c for c in range(w) if all(g[r][c] == 2 for r in range(h))]
    if bool(guide_rows) == bool(guide_cols):
        return g
    # The guide identifies the translation axis; other non-background cells form the motif.
    bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    motif = [(r, c, g[r][c]) for r in range(h) for c in range(w)
             if g[r][c] not in (bg, 2)]
    if not motif:
        return g
    rs = [r for r, c, v in motif]
    cs = [c for r, c, v in motif]
    if guide_rows:
        line = guide_rows[0]
        # Position the motif's bounding box immediately next to the guide.
        dr = (line - 1 - max(rs)) if min(rs) > line else (line + 1 - min(rs))
        far_edge = min(rs) + dr - 1 if min(rs) > line else max(rs) + dr + 1
        for r, c, v in motif:
            g[r][c] = bg
        for r, c, v in motif:
            nr = r + dr
            if 0 <= nr < h:
                g[nr][c] = v
        if 0 <= far_edge < h:
            for c in range(w):
                if g[far_edge][c] == bg:
                    g[far_edge][c] = 8
    else:
        line = guide_cols[0]
        dc = (line - 1 - max(cs)) if min(cs) > line else (line + 1 - min(cs))
        far_edge = min(cs) + dc - 1 if min(cs) > line else max(cs) + dc + 1
        for r, c, v in motif:
            g[r][c] = bg
        for r, c, v in motif:
            nc = c + dc
            if 0 <= nc < w:
                g[r][nc] = v
        if 0 <= far_edge < w:
            for r in range(h):
                if g[r][far_edge] == bg:
                    g[r][far_edge] = 8
    return g

if __name__ == '__main__':
